import hashlib
candidates = [
    "60000TBENCH-SALT",
    "6'0000TBENCH-SALT",
    "60000TBENCH-SALT'",
    "6'0000TBENCH-SALT'",
    "6\"0000TBENCH-SALT",
    "6\"0000TBENCH-SALT\"",
]
with open('/app/code.png','rb') as f:
    data=f.read()

ho = hashlib.sha256(data).digest()
ho_hex = hashlib.sha256(data).hexdigest()
ho_hex_bytes = ho_hex.encode()

for salt in candidates:
    salt_bytes = salt.encode()
    combos = [
        ('ho_bytes', ho),
        ('ho_hex_bytes', ho_hex_bytes),
    ]
    for desc, ho_val in combos:
        # slice options
        for slice_type in ['bytes','hex','none']:
            if slice_type=='bytes':
                slice_val = ho[:10]
            elif slice_type=='hex':
                slice_val = ho_hex[:10].encode()
            else:
                slice_val = b''
            # build inputs with separators: none, b'||'
            for sep in [b'', b'||']:
                # permutations order
                parts_list = [
                    ('ho_slice_salt', [ho_val, slice_val, salt_bytes]),
                    ('ho_salt_slice', [ho_val, salt_bytes, slice_val]),
                    ('slice_ho_salt', [slice_val, ho_val, salt_bytes]),
                    ('salt_ho_slice', [salt_bytes, ho_val, slice_val]),
                    ('salt_slice_ho', [salt_bytes, slice_val, ho_val]),
                    ('slice_salt_ho', [slice_val, salt_bytes, ho_val]),
                ]
                for order_name, parts in parts_list:
                    # join with separator
                    payload = sep.join([p for p in parts if p!=b''])
                    if not payload:
                        continue
                    H=hashlib.sha256(payload).hexdigest()
                    if H.startswith('bee26a'):
                        print('match', salt, desc, slice_type, sep, order_name, H)

print('done')
